    source: "lms",
    studentId,
    recordId: `LMS-${digest({ studentId, values, last })}`,
    observedAt: now.toISOString(),
    semester: rows.rows[0]?.term ?? "2026-ODD",
    state: rows.rows.length ? "present" : "missing",
    synthetic: process.env.CORE_IDENTITY_REALM !== "institutional",
